// Extract notification and profile data from Supabase webhook payload
const payload = $input.item.json;
const body = payload.body || payload;
const record = body.record || body;
const profile = body.profile || {};

const userId = record.user_id;
const notificationType = record.type || 'general';
const rawMessage = record.message || 'You have a new notification on Linkup Marketplace.';
const rawPhone = profile.phone || record.phone || '';
const displayName = profile.display_name || record.display_name || 'Valued Member';

// --- Phone Number Sanitizer (Nigerian standard & international E.164) ---
let cleanPhone = String(rawPhone).trim().replace(/[^0-9+]/g, '');

if (cleanPhone.startsWith('+')) {
  cleanPhone = cleanPhone.substring(1);
}

// If local Nigerian number (e.g. 080..., 070..., 081..., 090..., 091...)
if (cleanPhone.startsWith('0') && cleanPhone.length === 11) {
  cleanPhone = '234' + cleanPhone.substring(1);
}

const isValidPhone = cleanPhone.length >= 10 && cleanPhone.length <= 15;

// --- WhatsApp Message Content Formatter with Emojis & Bold text ---
let headerEmoji = '🔔';
let categoryTitle = 'Notification';

switch (notificationType.toLowerCase()) {
  case 'order_update':
  case 'order':
  case 'order_placed':
    headerEmoji = '📦';
    categoryTitle = 'Order Update';
    break;
  case 'new_product':
    headerEmoji = '✨';
    categoryTitle = 'New Product Alert';
    break;
  case 'payout':
  case 'payout_released':
  case 'wallet':
    headerEmoji = '💰';
    categoryTitle = 'Payment & Wallet Update';
    break;
  case 'assigned':
  case 'delivery':
  case 'shipment':
    headerEmoji = '🛵';
    categoryTitle = 'Logistics & Delivery';
    break;
  case 'kyc':
    headerEmoji = '🛡️';
    categoryTitle = 'KYC Verification';
    break;
  default:
    headerEmoji = '🔔';
    categoryTitle = 'Marketplace Alert';
}

const whatsappMessage = `${headerEmoji} *${categoryTitle} — Linkup Marketplace*\n\nHello *${displayName}*,\n\n${rawMessage}\n\n👉 *Visit your dashboard:* https://www.linkupng.com\n\n_Warm regards,_\n*Damian from Linkup Marketplace*`;

return [{
  json: {
    notification_id: record.id,
    user_id: userId,
    type: notificationType,
    display_name: displayName,
    raw_phone: rawPhone,
    phone: cleanPhone,
    phone_with_plus: '+' + cleanPhone,
    whatsapp_to: 'whatsapp:+' + cleanPhone,
    is_valid_phone: isValidPhone,
    message: whatsappMessage,
    original_message: rawMessage,
    timestamp: new Date().toISOString()
  }
}];
